#!/usr/bin/env node
/**
 * Tests for the pure rules of the deliver flow v2 in workflows/impl-review-loop.js: blocks, step budget, size from the
 * block count, readers, verifier and question policy. The shared harness is tools/impl-review-loop.harness.mjs.
 *
 *   node --test tools/impl-review-loop-blocks.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { blocksFor, lanesFor, lanesWorth, stepBudget, sizeFor, blockReader, finalReadersFor, verifierFor, ARBITER, questionPolicy } from './impl-review-loop.harness.mjs';

const tasks = (n, extra = {}) => Array.from({ length: n }, (_, i) => ({ id: `t${i + 1}`, title: `task ${i + 1}`, files: [], dependsOn: [], tdd: false, criteria: [], ...(extra[i + 1] ?? {}) }));
const shape = (blocks) => blocks.map((b) => b.length);

// ── blocks ─────────────────────────────────────────────────────────────────
test('given four tasks, when the blocks are cut, then there is one block of four', () => {
  // Given
  const plan = tasks(4);
  // When
  const blocks = blocksFor(plan);
  // Then
  assert.deepEqual(shape(blocks), [4]);
});

test('given five tasks, when the blocks are cut, then there are two blocks of three and two', () => {
  // Given
  const plan = tasks(5);
  // When
  const blocks = blocksFor(plan);
  // Then
  assert.deepEqual(shape(blocks), [3, 2]);
});

test('given ten tasks, when the blocks are cut, then there are three blocks of four, three and three', () => {
  // Given
  const plan = tasks(10);
  // When
  const blocks = blocksFor(plan);
  // Then
  assert.deepEqual(shape(blocks), [4, 3, 3]);
});

test('given a task that depends on a later one, when the blocks are cut, then the order follows the dependency', () => {
  // Given
  const plan = tasks(3, { 1: { dependsOn: ['t3'] } });
  // When
  const order = blocksFor(plan).flat().map((t) => t.id);
  // Then
  assert.deepEqual(order, ['t2', 't3', 't1']);
});

test('given a dependency cycle, when the blocks are cut, then the plan is refused and the cycle is named', () => {
  // Given
  const plan = tasks(3, { 1: { dependsOn: ['t2'] }, 2: { dependsOn: ['t1'] } });
  // When
  const cut = () => blocksFor(plan);
  // Then
  assert.throws(cut, (e) => e instanceof Error && /t1/.test(e.message) && /t2/.test(e.message) && !/t3/.test(e.message));
  assert.throws(() => blocksFor(tasks(1, { 1: { dependsOn: ['ghost'] } })), /ghost/);
});

test('given a task that depends on a cycle without being in it, when the blocks are cut, then only the cycle is named', () => {
  // Given
  const plan = tasks(3, { 1: { dependsOn: ['t2'] }, 2: { dependsOn: ['t1'] }, 3: { dependsOn: ['t1'] } });
  // When
  const cut = () => blocksFor(plan);
  // Then
  assert.throws(cut, (e) => /cycle among tasks: t1, t2$/.test(e.message));
});

test('given two tasks with the same id, when the blocks are cut, then the plan is refused and the id is named', () => {
  // Given
  const plan = [{ id: 't1' }, { id: 't1' }];
  // When
  const cut = () => blocksFor(plan);
  // Then
  assert.throws(cut, /duplicate task id: t1/);
});

// ── lanes ──────────────────────────────────────────────────────────────────
const ids = (lanes) => lanes.map((lane) => lane.map((t) => t.id));

test('given two task groups with no shared file or dependency, when the lanes are computed, then there are two lanes', () => {
  // Given
  const plan = tasks(4, { 1: { files: ['src/a/one.cs'] }, 2: { files: ['src/a/two.cs'], dependsOn: ['t1'] }, 3: { files: ['src/b/one.cs'] }, 4: { files: ['src/b/two.cs'], dependsOn: ['t3'] } });
  // When
  const lanes = lanesFor(plan);
  // Then
  assert.deepEqual(ids(lanes), [['t1', 't2'], ['t3', 't4']]);
});

test('given two tasks that share a file, when the lanes are computed, then they are in the same lane', () => {
  // Given
  const plan = tasks(3, { 1: { files: ['src/a.cs'] }, 2: { files: ['./SRC/a.cs'] }, 3: { files: ['src/c.cs'] } });
  // When
  const lanes = lanesFor(plan);
  // Then
  assert.deepEqual(ids(lanes), [['t1', 't2'], ['t3']]);
});

test('given a task whose file is inside a directory another task owns, when the lanes are computed, then they are in the same lane', () => {
  // Given
  const plan = tasks(3, { 1: { files: ['src/orders/'] }, 2: { files: ['src/orders/query.cs'] }, 3: { files: ['src/c.cs'] } });
  // When
  const lanes = lanesFor(plan);
  // Then
  assert.deepEqual(ids(lanes), [['t1', 't2'], ['t3']]);
});

test('given a task chain through a third task, when the lanes are computed, then the dependency is followed transitively', () => {
  // Given
  const plan = tasks(4, { 1: { files: ['a'] }, 2: { files: ['b'], dependsOn: ['t1'] }, 3: { files: ['c'], dependsOn: ['t2'] }, 4: { files: ['d'] } });
  // When
  const lanes = lanesFor(plan);
  // Then
  assert.deepEqual(ids(lanes), [['t1', 't2', 't3'], ['t4']]);
});

test('given a task that names no file, when the lanes are computed, then everything is one lane', () => {
  // Given
  const plan = tasks(3, { 1: { files: ['a'] }, 3: { files: ['c'] } });
  // When
  const lanes = lanesFor(plan);
  // Then
  assert.deepEqual(ids(lanes), [['t1', 't2', 't3']]);
});

test('given lanes of two and two tasks, when their worth is asked, then they pay; of three and one, or one lane, they do not', () => {
  // Given
  const lane = (n) => Array.from({ length: n }, (_, i) => ({ id: `x${i}` }));
  // When
  const worth = [[lane(2), lane(2)], [lane(3), lane(1)], [lane(4)], [lane(2), lane(1), lane(1)]].map(lanesWorth);
  // Then
  assert.deepEqual(worth, [true, false, false, true]);
});

test('given a block of three tasks, when its budget is computed, then it is 28 turns', () => {
  // Given
  const taskCount = 3;
  // When
  const budget = stepBudget(taskCount);
  // Then
  assert.equal(budget, 28);
  assert.equal(stepBudget(4), 34);
  assert.equal(stepBudget(5), 35);
});

// ── size from the block count ──────────────────────────────────────────────
test('given one block and no size passed, when the size is computed, then it is M', () => {
  // Given
  const blockCount = 1;
  // When
  const size = sizeFor(undefined, [], blockCount);
  // Then
  assert.equal(size, 'M');
});

test('given three blocks, when the size is computed, then it is L', () => {
  // Given
  const blockCount = 3;
  // When
  const size = sizeFor(undefined, [], blockCount);
  // Then
  assert.equal(size, 'L');
  assert.equal(sizeFor('M', [], 2), 'L');
});

test('given S and a data axis, when the size is computed, then it is M', () => {
  // Given
  const axes = ['data'];
  // When
  const size = sizeFor('S', axes, 1);
  // Then
  assert.equal(size, 'M');
});

test('given S and logic only, when the size is computed, then it stays S', () => {
  // Given
  const axes = ['logic'];
  // When
  const size = sizeFor('S', axes, 1);
  // Then
  assert.equal(size, 'S');
});

test('given three risk axes and one block, when the size is computed, then it is M, not L', () => {
  // Given
  const axes = ['performance', 'data', 'security'];
  // When
  const size = sizeFor(undefined, axes, 1);
  // Then
  assert.equal(size, 'M');
});

// ── readers, verifier, question policy ─────────────────────────────────────
const spec = (readers) => readers.map((r) => `${r.key}:${r.model}:${r.effort}`);

test('given an M change with no risk axis, when the final readers are picked, then there is one reader B on sonnet at high', () => {
  // Given
  const touches = [];
  // When
  const readers = finalReadersFor('M', touches, false, false);
  // Then
  assert.deepEqual(spec(readers), ['B:sonnet:high']);
});

test('given an M change with a security axis, when the final readers are picked, then reader B is on opus at high', () => {
  // Given
  const touches = ['security'];
  // When
  const readers = finalReadersFor('M', touches, false, false);
  // Then
  assert.deepEqual(spec(readers), ['B:opus:high', 'security:sonnet:high']);
});

test('given an M change with three risk axes, when the final readers are picked, then reader B is on opus at high', () => {
  // Given
  const touches = ['money', 'concurrency', 'contract'];
  // When
  const readers = finalReadersFor('M', touches, false, false);
  // Then
  assert.deepEqual(spec(readers), ['B:opus:high']);
});

test('given an M change with logic and two other axes, when the final readers are picked, then reader B stays on sonnet', () => {
  // Given
  const touches = ['logic', 'money', 'contract'];
  // When
  const readers = finalReadersFor('M', touches, false, false);
  // Then
  assert.deepEqual(spec(readers), ['B:sonnet:high']);
});

test('given a wide M change, when the final readers are picked, then reader B is on opus unless the change is mechanical', () => {
  // Given
  const wide = true;
  // When
  const plain = finalReadersFor('M', [], false, wide);
  const mechanical = finalReadersFor('M', [], true, wide);
  // Then
  assert.deepEqual(spec(plain), ['B:opus:high']);
  assert.deepEqual(spec(mechanical), ['B:sonnet:high']);
});

test('given an L change, when the final readers are picked, then reader B on opus at high and a second reader on sonnet at high', () => {
  // Given
  const size = 'L';
  // When
  const readers = finalReadersFor(size, [], false, false);
  // Then
  assert.deepEqual(spec(readers), ['A:sonnet:high', 'B:opus:high']);
  assert.ok(readers.every((r) => r.agentType === 'code-reviewer' && r.whole));
});

test('given a fix round with a P1, when the verifier is picked, then it is opus at medium', () => {
  // Given
  const round = { hasP1: true, maxFixLines: 3 };
  // When
  const verifier = verifierFor(round);
  // Then
  assert.deepEqual(verifier, { agentType: 'code-reviewer', model: 'opus', effort: 'medium' });
});

test('given a fix round of 31 changed lines, when the verifier is picked, then it is opus at medium', () => {
  // Given
  const round = { hasP1: false, maxFixLines: 31 };
  // When
  const verifier = verifierFor(round);
  // Then
  assert.deepEqual(verifier, { agentType: 'code-reviewer', model: 'opus', effort: 'medium' });
});

test('given a fix round of small P2 fixes, when the verifier is picked, then it is sonnet at high', () => {
  // Given
  const round = { hasP1: false, maxFixLines: 30 };
  // When
  const verifier = verifierFor(round);
  // Then
  assert.deepEqual(verifier, { agentType: 'code-reviewer', model: 'sonnet', effort: 'high' });
});

test('given the flow v2 roles, when the arbiter and the block reader are read, then the arbiter is opus at medium and the block reader sonnet at high', () => {
  // Given
  const roles = { ARBITER, blockReader };
  // When
  const { ARBITER: arbiter, blockReader: reader } = roles;
  // Then
  assert.deepEqual(arbiter, { agentType: 'code-reviewer', model: 'opus', effort: 'medium' });
  assert.deepEqual(reader, { key: 'A', agentType: 'code-reviewer', model: 'sonnet', effort: 'high' });
});

test('given a reversible question with a default on the logic axis, when the policy is asked, then it answers default', () => {
  // Given
  const q = { question: 'sort ascending?', default: 'ascending', reversible: true, axis: 'logic' };
  // When
  const policy = questionPolicy(q);
  // Then
  assert.equal(policy, 'default');
  assert.equal(questionPolicy({ ...q, default: '' }), 'stop');
  assert.equal(questionPolicy({ ...q, reversible: false }), 'stop');
});

test('given a reversible question on the data axis, when the policy is asked, then it answers stop', () => {
  // Given
  const q = { question: 'drop the column?', default: 'keep it', reversible: true, axis: 'data' };
  // When
  const policy = questionPolicy(q);
  // Then
  assert.equal(policy, 'stop');
  for (const axis of ['contract', 'money', 'security']) assert.equal(questionPolicy({ ...q, axis }), 'stop', axis);
});

test('given a reversible question with a missing, unknown or capitalised stop axis, when the policy is asked, then it answers stop', () => {
  // Given
  const q = { question: 'sort ascending?', default: 'ascending', reversible: true };
  // When
  const policies = [undefined, 'whatever', 'Security', ' DATA '].map((axis) => questionPolicy({ ...q, axis }));
  // Then
  assert.deepEqual(policies, ['stop', 'stop', 'stop', 'stop']);
  assert.equal(questionPolicy({ ...q, axis: 'Logic' }), 'default');
});

test('given a question whose reversible flag is not the boolean true, when the policy is asked, then it answers stop', () => {
  // Given
  const q = { question: 'sort ascending?', default: 'ascending', axis: 'logic' };
  // When
  const policies = ['false', 'true', 1].map((reversible) => questionPolicy({ ...q, reversible }));
  // Then
  assert.deepEqual(policies, ['stop', 'stop', 'stop']);
});
